        { q: 'مِنْ عَنَاصِرِ الْبِطَاقَةِ التَّعْرِيفِيَّةِ:', opts: ['مَكَانُ السَّكَنِ', 'لَوْنُ الْمَلَابِسِ', 'نَوْعُ الطَّعَامِ'], correct: 'مَكَانُ السَّكَنِ' },
        { q: 'فِي الْجُمْلَةِ (عُمْرِي تِسْعُ سَنَوَاتٍ) أَيُّ عُنْصُرٍ هَذَا؟', opts: ['الْعُمْرُ', 'الِاسْمُ', 'الْهِوَايَةُ'], correct: 'الْعُمْرُ' }
