      text: "يَلْعَبُ الْأَطْفَالُ كُرَةَ الْقَدَمِ فِي فَرِيقٍ وَاحِدٍ، وَيُشَارِكُونَ صَدِيقَهُمْ ذَا الْإِعَاقَةِ بِكُلِّ تَعَاوُنٍ وَسَعَادَةٍ.\nالنَّجَاحُ فِي الرِّيَاضَةِ يَحْتَاجُ إِلَى التَّدْرِيبِ، وَتَنْفِيذِ نَصَائِحِ الْمُدَرِّبِ، وَالتَّعَاوُنِ مَعَ زُمَلَاءِ الْفَرِيقِ.\nيَشْعُرُ اللَّاعِبُونَ بِالْحَمَاسِ وَالْأُخُوَّةِ عِنْدَ اللَّعِبِ فِي فَرِيقٍ؛ لِأَنَّ نَجَاحَ الْفَرِيقِ هُوَ نَجَاحٌ لِلْجَمِيعِ.",
