      text: "التأسيس البلاغي (٢): الأسلوب الخبري والأسلوب الإنشائي:\n\n💡 السؤال السحري للتفريق في ثانية واحدة:\nهل الجملة تطلب مني شيئاً أو تعبر عن إنشاء (طلب / تعجب)، أم تنقل لي مجرد خبر ومعلومة؟\n\n١️⃣ الأسلوب الخبري:\n• تعريفه: كلام يحتمل الصدق أو الكذب لذاته.\n• أنواعه:\n  - خبر حقيقي: يعبر عن حقيقة ثابتة لا خلاف عليها (مثل: «الشمس تشرق من الشرق» | «ينتج الفلاحون المحاصيل»).\n  - خبر بلاغي: يعبر عن رأي أو فكرة بحسب وجهة نظر المتكلم (مثل: «المجتهد هو أفضل الرجال» | «طاعة الله سبيل الجنة»).\n• الغرض العام للأسلوب الخبري: التقرير والتوكيد والوصف ونقل الحقائق.\n\n٢️⃣ الأسلوب الإنشائي:\n• تعريفه: كلام لا يحتمل الصدق أو الكذب لذاته، ويشير إلى أمر أو طلب بعينه.\n• أنواعه الخمسة المقررة:\n  ١. الأمر: بصيغة فعل الأمر («اعمل بجد» | «قم للمعلم») أو المضارع المقترن بلام الأمر («لتحرصوا على العلم»).\n  ٢. النهي: بصيغة (لا الناهية + الفعل المضارع) الدالة على طلب الامتناع («لا تكذب» | «لا تضيعوا الوقت»).\n  ٣. النداء: بحروف النداء (يا - أيا - هيا - أي - الهمزة)، وقد تُحذف الأداة للدلالة على القرب («شباب مصر، اجتهدوا» أصلها «يا شباب مصر»).\n  ٤. الاستفهام: طلب العلم بشيء غير معلوم بأدوات الاستفهام («كيف حالك اليوم؟» | «أعلمت أشرف أو أجل...؟»).\n  ٥. التعجب: إظهار الدهشة والتعظيم («ما أروع التحلي بالأخلاق!» | «ما أجمل النيل!» | «سبحان الله!»).\n• الغرض العام للأساليب الإنشائية: جذب انتباه السامع، إثارة ذهنه، وتشويقه.\n\n🚨 احذر ٣ مطبات امتحانية شهيرة:\n١. (لا) النافية vs (لا) الناهية: «لا يُهْمِلُ المجتهد» (إخبار = خبري) مقابل «لا تُهْمِلْ واجبك» (طلب امتناع = إنشائي نهي).\n٢. النداء المحذوف الأداة: «طلاب العلم، ثابروا» (أسلوب إنشائي نداء).\n٣. (ما) النافية vs (ما) التعجبية: «ما أتقن الكسول عمله» (ما نافية = خبري) مقابل «ما أتقن عمل المخلص!» (تعجب = إنشائي).",
