      text: "التأسيس البلاغي (٣): الصورة الحسية ودلالات الحواس الخمس:\n\n🎯 تعريف الصورة الحسية:\nهي ألفاظ وتعبيرات وتصويرات يستخدمها الكاتب أو الشاعر؛ لنقل المشاعر والمعاني إلى خيال المتلقي عبر مخاطبة حواسه الخمس:\n\n| الحاسة | الكلمات المفتاحية والأمثلة | المشاعر الناتجة |\n| :--- | :--- | :--- |\n| 👁️ **بصرية (بالعين)** | الألوان، الضوء، الظلال، الأشكال، الحركة (مثل: «سطعت الشمس بأشعتها الذهبية» / «تلمع النجوم كلآلئ»). | التفاؤل، البهجة، الأمل، الجمال، الإشراق |\n| 👂 **سمعية (بالأذن)** | الأصوات، الصراخ، الهمس، خرير الماء، زقزقة العصافير، قصف الرعد (مثل: «عصفت الرياح ودوى الرعد»). | الرهبة، الخوف، الطمأنينة، السعادة، الانتباه |\n| 👃 **شمية (بالأنف)** | العطور، البخور، الأزهار، روائح الأطعمة الزكية (مثل: «فاحت رائحة الياسمين في الأرجاء»). | الانتعاش، الراحة، الشهية، السرور |\n| ✋ **لمسية (بالجلد)** | النعومة، الخشونة، البرودة، السخونة (مثل: «لمست قماشاً ناعماً كالحرير» / «ارتجف من برودة الماء»). | الدفء، الطمأنينة، القشعريرة، الحنان |\n| 👅 **تذوقية (باللسان)** | الحلو، المر، الشهد، العسل، العلقم، المالح، اللذيذ (مثل: «كلامه كالشهد في فمي»). | اللذة، القبول، الرضا، النفور (عند المرارة) |\n\n💡 تطبيق بيتي إيليا أبو ماضي في التذوق البلاغي:\n• «أَحْبِبْ فَيَغْدُ الكَوْخُ قَصْرًا نَيِّرًا ... وَابْغُضْ فَيُمْسِي الكَوْنُ سِجْنًا مُظْلِمَا»\n  - الصورة البصرية: (قصر نيّر مقابل سجن مظلم) توضح أثر الحب في نشر السعادة والنور وأثر الكره في الظلمة والضيق.\n• «كُنْ وَرْدَةً تَضُوعُ عِطْرًا ... وَلا تَكُنْ عَوْسَجًا» (صورة شمية ولمسية).",
