      text: "الدليل الذكي للقرائية وفك شفرات نصوص القراءة المتحررة:\n\n🗝️ أولاً: قاعدة الـ ٣٠ ثانية وقراءة النص كنظام كشافات:\n١. القراءة الكاشفة: اقرأ القطعة من البداية للنهاية لتحديد الموضوع والهدف العام.\n٢. تفكيك الفقرات بكشافات الربط:\n   • (ولكن - غير أن - بل - على الرغم من) $\\leftarrow$ تفيد الاستدراك وعكس الفكرة السابقة.\n   • (لذلك - من هنا - مما أدى إلى - أسفرت عن) $\\leftarrow$ تفيد النتيجة المترتبة.\n   • (إيماناً منه - رغبة في - لأن - من أجل) $\\leftarrow$ تفيد السبب والتعليل.\n\n🗝️ ثانياً: استخراج الفكرة الرئيسة والفرعية والضمنية:\n• الفكرة الرئيسة: المظلة الكبرى التي تشمل كامل النص (مثل: «تجسيد أحمد منسي كرمز للتضحية والفداء»).\n• الفكرة الفرعية: النقطة الخاصة بفقرة واحدة محددة (مثل: «حرص منسي على الجمع بين الشجاعة والعلم»).\n• الفكرة الضمنية: الرسالة المستترة التي يريد الكاتب إيصالها (مثل: «حب الوطن أفعال وتضحية لا مجرد شعارات»).\n\n🗝️ ثالثاً: استراتيجية القرائن الأربع لتخمين أي معنى غامض في الامتحان:\n١. قرينة الترادف والعطف بالواو: (اتسمت بالجدية والالتزام $\\leftarrow$ اتصفت).\n٢. قرينة التضاد والمقابلة: (لا نفرط فيها أو تمس بسوء $\\leftarrow$ لا نضيع / عكس نحافظ).\n٣. قرينة السبب والنتيجة: (عملية تطهير أسفرت عن القضاء على الإرهاب $\\leftarrow$ أدت إلى).\n٤. سياق الموقف وتخيل المشهد.\n\n🗝️ رابعاً: شفرة إجابة «بم يوحي التعبير؟»:\n• «علمته كيف يكون إنساناً قبل أن يكون جندياً» $\\leftarrow$ توحي بعظيم الأخلاق وتقديم الرحمة والإنسانية.\n• «لا يأكل قبل أن يتأكد أن كل جنوده تناولوا طعامهم» $\\leftarrow$ تدل على الإيثار وقمة التواضع والمسئولية.\n• «نموت ونحن رافعون رءوسنا» $\\leftarrow$ توحي بالعزة والكرامة والشموخ.",
