      text: "الدرس الثالث: القراءة «رسالة إلى المرأة المصرية» - د. نعمات أحمد فؤاد:\n\n✨ تمهيد وبطاقة الكاتبة:\n• الكاتبة: نعمات أحمد فؤاد، كاتبة ومفكرة مصرية بارزة، لُقبت بـ «عروس النيل» لشغفها العميق بمصر وتراثها.\n• الميلاد: ولدت بمدينة مغاغة بالمنيا عام ١٩٢٤م، وشغلت منصب مدير عام للمجلس الأعلى للثقافة.\n• أهم أعمالها: «آفاق مصرية»، «الإسلام وإنسان العصر»، «القاهرة في حياتي» (توفيت ٢٠١٦م).\n\n١️⃣ صفات جوهرية ميزت المرأة المصرية:\n«إلى تِلْكَ الَّتِي رَفَعَ التَّارِيخُ الْمِصْرِيُّ مِنْهَا مِثَالًا عاليًا (لِلْمِصْرِيَّةِ) عَبْرَ الْأَجْيَالِ، فَلَمْ تُغَيَّرْهَا الْأَيَّامُ، بَلْ زَادَهَا الْقِدَمُ أَصَالَةً وَجَلَالًا. إلى تِلْكَ الَّتِي غَذَّتِ الْحَضَارَةَ، وَصَاحَبَتِ الْمَدَنِيَّاتِ، وَأَعْطَتْ أَضْعَافَ مَا أَخَذَتْ، ثُمَّ كَانَتْ مِنْ قُوَّةِ الشَّخْصِيَّةِ بِحَيْثُ لَمْ تَخْدَعْهَا الْأَضْوَاءُ فَظَلَّتْ كَمَا هِيَ سَلِيمَةً نَقِيَّةً كَالْمَعْدِنِ الْكَرِيمِ، كَرِيمَةً وَفِيَّةً كَالنِّيلِ الْأَصِيْلِ، حَيَاتُهَا لِلْخِصْبِ وَالْإِنْتاجِ كَأَرْضِنَا الطَّيِّبَةِ. إلى تِلْكَ الصَّبُورِ الدَّءُوبِ، الَّتِي هَيْهَاتَ لِلْبَسَاطَةِ أَنْ تَحْجُبَ عَنَّا عَظَمَتَهَا.. إِنَّهَا أَكْبَرُ مِنَ الْمَظَاهِرِ، وَأَعْظَمُ مِنَ الزَّمَنِ نَفْسِهِ.. فَلَا أَحْدَاثُهُ وَلَا آلَامُهُ اسْتَطَاعَتْ أَنْ تُغَيَّرَ مِنْهَا شَيْئًا..»\n\n٢️⃣ المرأة المصرية رمز الكفاح ومصدر الإلهام:\n«لَوَّحَتِ الشَّمْسُ مِنْهَا الْوَجْهَ، وَلَكِنَّهُ بِسُمْرَتِهِ رَائِعُ آسِرٌ.. يَسْحَرُ بِالطَّيبَةِ وَالْوَدَاعَةِ وَصِدْقِ الْفِطْرَةِ الَّذِي يَفُوقُ كَثِيرًا أَصْبَاغَ الْحَضَارَةِ، وَعَرِقَتِ الْأَرْضُ مِنْهَا اليَدَيْنِ، وَلَكِنَّهُمَا بِمَعَالِمِ الْكِفَاحِ خَيْرٌ مِنْ أَيَادٍ كَثِيرَةٍ تَأْخُذُ مِنْهَا وَلَا تُعْطِي.. فَمَا أَبْعَدَ الْفَارِقَ بَيْنَ الْيَدِ الْعُلْيَا وَالْيَدِ السُّفْلَى! وضَوَى الْجَفَافُ مِنْهَا الْجِسْمَ، وَلَكِنَّهُ بِشُمُوخِ قَامَتِهِ إِلْهَامٌ لِلْفَنِّ، وَوَحْيٌ لِلشَّاعِرِ، وَنَمُوذَجٌ لِلرَّسَّامِ.. إِنَّهَا أَقْوَى مِنَ الْفَقْرِ نَفْسِهِ.. وَأَعْظَمُ مِنَ الزَّمَنِ؛ لِأَنَّ هَاتَيْنِ القُوَّتَينِ لَمْ تُغَيَّرَا جَوْهَرَهَا النَّفْسِي، فَظَلَّتْ كَرَائِمُهَا كَمَا هِيَ مِنْ وَفَاءٍ وَإِبَاءٍ وَبَلَاءٍ وَصَبْرٍ طَوِيلٍ.»\n\n٣️⃣ عرفان بالجميل:\n«إلى تِلْكَ الَّتِي امْتَزَجَتْ بِوَادِينَا، وَحَمَلَتْ طَابَعَهُ، فَجَمَعَتْ فِي كِيَانِهَا النَّحِيلِ طِيبَةَ الْأَرْضِ، وَعُذُوبَةَ السَّمَاءِ، وَصَبْرَ الصَّحْرَاءِ الَّذِي لَا يَنْفَدُ. إلى تِلْكَ الَّتِي فِي الْحُقُولِ تَنْسَابُ بَيْنَ أَعْوَادِ الذُّرَةِ، وَتَرَفَّقُ بَيْنَ سَنَابِلِ الْقَمْحِ، وَتَتَهَادَى عَلَى الْبِسَاطِ الْأَخْضَرِ، وَتَحْنُو عَلَى النِّيلِ مَعَ أَنْدَاءِ الْفَجْرِ وَبَسْمَةِ الشُّرُوقِ. فَكَمْ أَدَّتْ إِلَيْنَا جَمِيعًا وَمَا انْتَظَرَتْ جَزَاءً وَلَا نَالَتْهُ! عَلَى أَنِّي لَا أُسْدِي إِلَيْهَا هُنَا يَدًا وَلَا أُزْجِي عِرْفَانًا، فَإِنِّي إِنَّمَا أُخَاطِبُ نَفْسِي حِينَ أُخَاطِبُهَا. أُحَيِّي الْمِصْرِيَّةَ بِكَرَائِمِهَا، بِشَمَائِلِهَا، بِطَابِعِهَا الْأَصِيلِ، بِأَمْجَادِهَا جَمِيعًا. أُحَيِّي أُمِّي وَجَدَاتِي مُنْذُ فَجْرِ التَّارِيخِ الْمِصْرِيِّ إِلَى الْيَوْمِ.»",
