      text: "الدليل الذكي للقرائية (نصوص السيرة الذاتية والمقال الفكري):\n\n🗝️ أولاً: كيف تقرأ نصوص السيرة الذاتية وتستنتج سمات الكاتب؟\n١. تكرار أفعال اليقين والضمائر: تكرار العقاد لـ (إنني أؤمن... وأؤمن بالظروف... وأؤمن بالرغبة) يدل على: [شدة الاعتزاز بالنفس، وضوح الرؤية، واليقين التام بمبادئه].\n٢. الربط بين سلوك الطفولة والنتيجة في الكبر: دفع ثمن الكتب جزءاً بعد جزء من المصروف القليل يدل على: [١- الشغف المبكر بالعلم، ٢- الصبر والمثابرة والتضحية بالمغريات من أجل الهدف].\n\n🗝️ ثانياً: قاعدة «التآزر والتكامل» لحل أسئلة الربط الضمني:\n• عبارة العقاد الذهبية: «أؤمن بها مجتمعة ولا أؤمن بها متفرقة» $\\leftarrow$ هي المفتاح لإجابة أي سؤال عن عوامل النجاح؛ فالرغبة بلا عمل لا تكفي، والتشجيع بلا إرادة داخلية لا يصنع بطلاً ولا أديباً.\n\n🗝️ ثالثاً: استراتيجية فك شفرة الكلمات التراثية والعتيقة في الامتحان:\n١. استخدام حرف الجر لكشف الاتجاه:\n   • (حفزتني إلى) $\\leftarrow$ حرف الجر (إلى) يفيد الحركة والدفع للأمام $\\rightarrow$ شجعتني.\n   • (رَغِبَ فِي) = أحب وأراد × (رَغِبَ عَنْ) = كره وابتعد وترك.\n٢. السياق الزمني والترتيب المنطقي: (طفولة $\\leftarrow$ صِبَا $\\leftarrow$ شباب) $\\rightarrow$ الصبا مرحلة حداثة السن التي تلي الطفولة مباشرة.\n٣. فك شفرات المجاز في النصوص الفكرية: (مرآة الحضارة = تعكس عظمة الأجداد بوضوح) / (فجر التاريخ = بداياته الأولى).\n\n🗝️ رابعاً: نموذج الإجابة التحليلي لأسئلة المستويات العليا:\n• سؤال نبوءة الإمام محمد عبده («ما أجدر هذا أن يكون كاتباً بعد!») $\\leftarrow$ حللها من زاويتين:\n   ١. من جهة الإمام: نفاذ البصيرة ودقة الملاحظة وحرصه على رعاية المواهب.\n   ٢. من جهة العقاد: نبوغه وبراعته اللغوية المبكرة قبل الشهرة.\n• سؤال توازن المتحف الكبير بين الماضي والمستقبل:\n   - في الشكل والتصميم: مثلثات تماثل الأهرامات (يجمع بين العراقة والحداثة).\n   - في المضمون والهدف: صيانة الماضي بأحدث تقنيات المستقبل لخدمة الاقتصاد والنشء.",
