      text: "الدليل الذكي للقرائية وتحليل النصوص الوجدانية والاجتماعية (ختام الوحدة الثالثة):\n\n🟢 المحور الأول: كيف تفك شفرة المفردات في «المقال الاجتماعي النقدي»؟ (استراتيجية البوصلة):\n١. المعنى المعجمي vs المعنى السياقي (المراد):\n   • «أصبحت التكنولوجيا عَصَبَ الحياة» $\\rightarrow$ المراد بالسياق: [الأساس والمحرك الرئيس والعمود الفقري].\n   • «غَرْقَى في العالم الافتراضي» $\\rightarrow$ المراد بالسياق: [الانغماس الشديد وفقدان الوعي والسيطرة على الوقت].\n٢. استنتاج المعنى من «موقف الكاتب»:\n   • وصف سلبي: «حواجز صَمَّاء» $\\rightarrow$ [قاسية، مصمتة، خالية من المشاعر والدفء].\n   • حل إيجابي: «تَرْشِيد الاستخدام» $\\rightarrow$ [حسن الاستغلال، والاعتدال، والضبط].\n\n🟢 المحور الثاني: كيف تحلل «المقال النقدي» في القراءة المتحررة؟ (معادلة الميزان):\n• كفة الإيجابيات (تقريب المسافات، توفير الوقت) $\\leftrightarrow$ كفة السلبيات (العزلة، برود المشاعر، تفكك الأسرة).\n• موقف الكاتب الموضوعي: الكاتب لا يتناقض؛ فهو يثمن المنافع ويدعو إلى (الترشيد والتوازن) لخدمة الإنسانية.\n\n🟢 المحور الثالث: شفرات تذوق «الشعر الوجداني وشعر المناجاة»:\n١. الأدب في الدعاء: الأمر والنهي الموجه إلى الله تعالى غرضه البلاغي دائماً هو [الدعاء والتضرع والرجاء].\n٢. التضاد الوجداني: (الظلمة: دجى، غلس، غسق) $\\times$ (النور: نور، سراج، ألق) $\\rightarrow$ يبرز أن النفس بدون هداية الله تائهة في الظلمات.\n٣. تجسيد المعاني المعنوية: «توجني بعافية» (العافية تاج) - «أنت حصني» (رعاية الله حصن منيع لا يخترق).\n\n🟢 المحور الرابع: بنك التطبيقات الذكية للتقييم:\n• المفارقة التكنولوجية: التكنولوجيا قربت البعيد جغرافياً (آلاف الأميال) وباعدت القريب شعورياً (أفراد المائدة الواحدة)!\n• دقة الألفاظ: «أنت الملاذ إذا ما اشتدت الكرب» أدق من (أنت ملجأي في الشدائد)؛ لأن تعريف الطرفين يفيد القصر والحصر، والكرب هو الشدة التي تعتصر القلب والروح.",
