      text: "القسم الثالث: الدرس الثاني - الفعل المجرد والفعل المزيد:\n\n١️⃣ القاعدة النحوية:\nينقسم الفعل من حيث أصالة حروفه وزيادتها في صيغة الماضي إلى:\n• الفعل المجرد: هو ما كانت جميع حروفه أصلية في الماضي لا يمكن حذف أحدها إلا واختل المعنى، وينقسم إلى:\n  ١. مجرد ثلاثي: على وزن (فَعَلَ) مثل: (كَتَبَ — خَرَجَ — فَهِمَ — شَرِبَ — أَكَلَ — وَعَدَ — مَدَّ — قَالَ — سَعَى).\n  ٢. مجرد رباعي: على وزن (فَعْلَلَ) مثل: (دَحْرَجَ — زَلْزَلَ — وَسْوَسَ — طَمْأَنَ — بَعْثَرَ — هَرْوَلَ — سَيْطَرَ).\n\n• الفعل المزيد: هو ما زِيدَ على حروفه الأصلية حرف أو اثنان أو ثلاثة أحرف في الماضي، وينقسم إلى:\n  ١. مزيد ثلاثي:\n     - مزيد بحرف: (الهمزة: أَكْرَمَ | التضعيف: عَلَّمَ | الألف: شَارَكَ).\n     - مزيد بحرفين: (انْطَلَقَ [أ ن] | انْتَصَرَ [أ ت] | تَعَاوَنَ [ت ا] | تَعَلَّمَ [ت وتضعيف] | اخْضَرَّ [أ وتضعيف]).\n     - مزيد بثلاثة أحرف: (اسْتَخْرَجَ — اسْتَغْفَرَ — اسْتَقْبَلَ — اسْتَعَانَ [أ س ت]).\n  ٢. مزيد رباعي:\n     - مزيد بحرف: (التاء في أوله: تَدَحْرَجَ — تَزَلْزَلَ).\n     - مزيد بحرفين: (الهمزة والتضعيف: اطْمَأَنَّ — اقْشَعَرَّ — اشْمَأَزَّ).\n\n٢️⃣ تنبيهات وملاحظات امتحانية مهمة (حروف ليست من الزيادة):\n١. أحرف المضارعة (أَنَيْتُ) ليست من حروف الزيادة (يَكْتُبُ $\\rightarrow$ ماضيه كَتَبَ $\\rightarrow$ مجرد ثلاثي).\n٢. تاء التأنيث والضمائر المتصلة ليست من حروف الزيادة (كَتَبُوا / كَتَبَتْ $\\rightarrow$ كَتَبَ $\\rightarrow$ مجرد ثلاثي).\n٣. القاعدة الذهبية: لا تحكم على الفعل في المضارع أو الأمر أو مع الضمير، بل رُدَّهُ دائماً إلى الماضي المفرد المذكر مع (هُوَ).\n٤. أقصى عدد لحروف الفعل بعد الزيادة هو ٦ أحرف.\n\n📝 التدريبات النموذجية المتدرجة واختبر نفسك:\n• «يَحْرِصُ الطلابُ المخلصونَ عَلَى أَنْ يَسْتَفِيدُوا مِنْ أَوْقَاتِهِمْ، فَهُمْ يَقْرَءُونَ الْكُتُبَ النَّافِعَةَ، وَيَتَعَاوَنُونَ فِي حَلِّ الْمُشْكِلَاتِ، وَقَدْ زَلْزَلَ الْعِلْمُ الْجَهْلَ فِي كُلِّ مَكَانٍ؛ لِذَلِكَ اسْتَحَقَّ الْعُلَمَاءُ التَّقْدِيرَ.»\n• إعراب: الطلابُ: فاعل مرفوع بالضمة | الْكُتُبَ: مفعول به منصوب بالفتحة | الْجَهْلَ: مفعول به منصوب بالفتحة | التَّقْدِيرَ: مفعول به منصوب بالفتحة.\n• استخراج الأفعال ونوعها:\n  - يَحْرِصُ: ماضيه (حَرَصَ) $\\rightarrow$ مجرد ثلاثي.\n  - يَسْتَفِيدُوا: ماضيه (اسْتَفَادَ) $\\rightarrow$ مزيد ثلاثي بـ ٣ أحرف (الهمزة والسين والتاء).\n  - يَقْرَءُونَ: ماضيه (قَرَأَ) $\\rightarrow$ مجرد ثلاثي.\n  - يَتَعَاوَنُونَ: ماضيه (تَعَاوَنَ) $\\rightarrow$ مزيد ثلاثي بحرفين (التاء والألف).\n  - زَلْزَلَ: $\\rightarrow$ مجرد رباعي.\n  - اسْتَحَقَّ: $\\rightarrow$ مزيد ثلاثي بـ ٣ أحرف (الهمزة والسين والتاء وأصله حَقَّ).\n• تصويب الخطأ: «يَعِدُونَ» مجرد ثلاثي (وَعَدَ) والواو والنون ليستا زيادة | «اخْضَرَّ» مزيد بحرفين (الهمزة والتضعيف في الراء).",
