      text: "الدليل الشارح المبسط والتفاعلي (كبسولة الفعل الصحيح):\n\n🛡️ ١. ميزان الكشف السريع في ٣ ثوانٍ (خطوات التجريد الثلاث):\nالفعل في الامتحان (يَسْتَرِدُّونَ / يُسَائِلُونَ / يَتَعَلَّمُونَ):\n١. احذف حروف المضارعة والضمائر وحروف الزيادة.\n٢. هات الماضي المجرد (٣ أو ٤ حروف) مع (هُوَ).\n٣. طبق القاعدة:\n   - فيه همزة أصلية $\\rightarrow$ [صحيح مهموز] (أَكَلَ / سَأَلَ / قَرَأَ).\n   - فيه تشديد أو تكرار أصلي $\\rightarrow$ [صحيح مضعف] (مَدَّ / زَلْزَلَ).\n   - خالٍ من الهمزة والتضعيف $\\rightarrow$ [صحيح سالم] (كَتَبَ / فَهِمَ / عَمِلَ).\n\n🚨 ٢. احذر المطبَّين الامتحانيين الشهيرين:\n• المطب الأول: (الهمزة الزائدة vs الهمزة الأصلية):\n  - الفعل «أَكْرَمَ» $\\rightarrow$ حذفت همزة الزيادة $\\rightarrow$ المجرد «كَرَمَ» $\\rightarrow$ إذن هو [صحيح سالم] (وليس مهموزاً!).\n  - الفعل «أَمَرَ / سَأَلَ» $\\rightarrow$ الهمزة أصلية في جذر الفعل $\\rightarrow$ إذن هو [صحيح مهموز].\n• المطب الثاني: (التضعيف الزائد vs التضعيف الأصلي):\n  - الفعل «عَلَّمَ / قَدَّمَ / خَطَّطَ» $\\rightarrow$ تضعيف الحرف الأوسط زائد $\\rightarrow$ المجرد «عَلِمَ / قَدِمَ» $\\rightarrow$ إذن هو [صحيح سالم].\n  - الفعل «عَدَّ / مَدَّ / حَبَّ» $\\rightarrow$ التضعيف أصلي (ثانيه وثالثه من جنس واحد) $\\rightarrow$ إذن هو [صحيح مضعف ثلاثي].\n\n📊 ٣. جدول التطبيق الذكي للتصنيف:\n• يَتَسَاءَلُونَ $\\rightarrow$ سَأَلَ $\\rightarrow$ به همزة أصلية $\\rightarrow$ [صحيح مهموز].\n• يَسْتَمِدُّ $\\rightarrow$ مَدَّ $\\rightarrow$ به تضعيف أصلي $\\rightarrow$ [صحيح مضعف ثلاثي].\n• يَتَزَلْزَلُ $\\rightarrow$ زَلْزَلَ $\\rightarrow$ به تكرار رباعي $\\rightarrow$ [صحيح مضعف رباعي].\n• يُشَاهِدُونَ $\\rightarrow$ شَهِدَ $\\rightarrow$ خالٍ من الهمز والتضعيف $\\rightarrow$ [صحيح سالم].",
