      text: "القسم الثالث: الدرس الثاني - كتابة الهمزة على الواو:\n\n١️⃣ القاعدة الإملائية:\n• تُكْتَبُ الهمزة المتوسطة على الواو (ؤ) إذا كانت الضمة هي أقوى الحركتين (بين حركة الهمزة وحركة ما قبلها)، بشرط ألا توجد في الهمزة أو فيما قبلها كسرة.\n\n• مواضع كتابة الهمزة المتوسطة على الواو (خمسة مواضع):\n  ١. أن تكون الهمزة مضمومة وما قبلها مضموم (ضمة + ضمة = الضمة):\n     - أمثلة: رُؤُوس — كُؤُوس — فُؤُوس — شُؤُون.\n  ٢. أن تكون الهمزة مضمومة وما قبلها مفتوح (ضمة + فتحة = الضمة أقوى):\n     - أمثلة: يَؤُمُّ — لَؤُمَ — يَؤُودُ — يَقْرَؤُهُ — رَؤُوف — دَؤُوب — يَؤُزُّ.\n  ٣. أن تكون الهمزة مضمومة وما قبلها ساكن (ضمة + سكون = الضمة أقوى):\n     - أمثلة: مَسْؤُول — تَفَاؤُل — تَسَاؤُل — تَشَاؤُم — يَؤُوس — أَرْزُؤُهُ.\n  ٤. أن تكون الهمزة مفتوحة وما قبلها مضموم (فتحة + ضمة = الضمة أقوى):\n     - أمثلة: سُؤَال — مُؤَنَّث — مُؤَخَّر — فُؤَاد — يُؤَدِّي — مُؤَذِّن — مُؤَلِّف.\n  ٥. أن تكون الهمزة ساكنة وما قبلها مضموم (سكون + ضمة = الضمة أقوى):\n     - أمثلة: مُؤْمِن — مُؤْذِي — رُؤْيَة — بُؤْرَة — لُؤْلُؤ — مُؤْتَمَر — يُؤْلِمُ.\n\n٢️⃣ تنبيهات وملاحظات امتحانية مهمة:\n• توالي الواوات في الكتابة: في كلمات مثل: (رُؤُوس — مَسْؤُول — شُؤُون)، يجوز كتابتها على الواو (رُؤُوس / مَسْؤُول) وهو الرسم القياسي الأصلي المعتمد مدرسياً، ويجوز عند بعض المجامع كتابتها على نبرة إذا أمكن اتصال ما بعدها بما قبلها (مَسْئُول) أو على السطر (رُءُوس) لكراهة توالي الأمثال، والقاعدة المدرسية تعتمد كتابتها على الواو.\n\n📝 التدريبات النموذجية المتدرجة واختبر نفسك:\n• صح وخطأ:\n  - تكتب على الواو إذا كانت مفتوحة وما قبلها مضموم (صواب، لأن الضمة أقوى من الفتحة).\n  - كلمة «مُؤْمِن» كتبت على الواو لأنها مضمومة وما قبلها ساكن (خطأ، لأنها ساكنة وما قبلها مضموم).\n  - كلمة «تَفَاؤُل» كتبت على الواو لأنها مضمومة وما قبلها ألف مد ساكنة (صواب).\n• اختر السبب وإكمال الفراغات:\n  - «سُؤَال» $\\rightarrow$ مفتوحة وما قبلها مضموم.\n  - «يَؤُمُّ» $\\rightarrow$ مضمومة وما قبلها مفتوح.\n  - «رُؤْيَة» $\\rightarrow$ ساكنة وما قبلها مضموم.\n  - «المؤمن الصادق» $\\rightarrow$ ساكنة بعد ضم | «سؤال المعلم» $\\rightarrow$ مفتوحة بعد ضم | «بتفاؤل كبير» $\\rightarrow$ مضمومة بعد سكون.\n• تصويب الأخطاء:\n  - «يَئُمُّ الإمام المصلين» $\\rightarrow$ «يَؤُمُّ» (الهمزة مضمومة بعد فتح والضمة أقوى فتكتب على الواو).\n  - «سمعت مُئَذِّن المسجد» $\\rightarrow$ «مُؤَذِّنَ» (الهمزة مفتوحة بعد ضم والضمة أقوى فتكتب على الواو).",
